import React from 'react';

function PlayerInfo({ gameState, playerId, onMarkReady }) {
  if (!gameState) return <div>Loading...</div>;

  const { players, gameStarted, currentPlayer, gamePhase } = gameState;
  const currentPlayerData = players[playerId];
  const playerList = Object.values(players);

  return (
    <div className="game-info">
      <h3>Game Information</h3>

      <div className="game-status">
        <p>
          <strong>Status:</strong>{' '}
          {gamePhase === 'waiting'
            ? 'Waiting for players'
            : gamePhase === 'playing'
            ? 'Game in progress'
            : 'Game ended'}
        </p>
        <p>
          <strong>Players:</strong> {playerList.length}/6
        </p>
      </div>

      {gameStarted && currentPlayer && (
        <div className="turn-info">
          <p>
            <strong>Current Turn:</strong> {players[currentPlayer]?.name} (
            {players[currentPlayer]?.character})
          </p>
        </div>
      )}

      <div className="player-list">
        <h4>Players</h4>
        {playerList.map((player) => (
          <div
            key={player.id}
            className={`player-item ${
              player.id === currentPlayer ? 'current-turn' : ''
            } ${player.isReady ? 'ready' : ''}`}
          >
            <div>
              <strong>{player.name}</strong>
              <br />
              <small>{player.character}</small>
              {player.eliminated && <span> (Eliminated)</span>}
            </div>
            <div>
              {gameStarted && <span>Cards: {player.cardCount}</span>}
              {!gameStarted && (player.isReady ? '✓ Ready' : 'Not Ready')}
            </div>
          </div>
        ))}
      </div>

      {!gameStarted && currentPlayerData && !currentPlayerData.isReady && (
        <button className="btn" onClick={onMarkReady}>
          Mark Ready
        </button>
      )}

      {!gameStarted && playerList.length < 3 && (
        <p>
          <small>Need at least 3 players to start</small>
        </p>
      )}

      {currentPlayerData?.cards && (
        <div className="cards-hand">
          <h4>Your Cards</h4>
          <div className="cards-list">
            {currentPlayerData.cards.map((card, index) => (
              <span key={index} className="card">
                {card}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default PlayerInfo;
